sp_widget.client_script:
api.controller = function(spModal, $window, $interval) { 

    var c = this; 


    c.idCardFile = null; 
    c.idCardFileName = ""; 

    c.profileSysId = ""; 

    c.isSubmitting = false; 
    c.isCreatingAccount = false; 

    c.verificationSubmitted = false; 
    c.idApproved = false; 

    var statusTimer = null; 


    // ========================================= 
    // ID CARD FILE 
    // ========================================= 

    c.idCardSelected = function(input) { 

        if (!input.files || input.files.length === 0) { 

            c.idCardFile = null; 
            c.idCardFileName = ""; 

            return; 
        } 

        var file = input.files[0]; 

        var maxSize = 5 * 1024 * 1024; 

        if (file.size > maxSize) { 

            spModal.alert( 
                "ID card file must be smaller than 5 MB." 
            ); 

            input.value = ""; 

            return; 
        } 


        var allowedTypes = [ 
            "image/jpeg", 
            "image/png", 
            "application/pdf" 
        ]; 


        if (allowedTypes.indexOf(file.type) === -1) { 

            spModal.alert( 
                "Please upload JPG, JPEG, PNG or PDF." 
            ); 

            input.value = ""; 

            return; 
        } 


        var reader = new FileReader(); 


        reader.onload = function(event) { 

            var base64Data = 
                event.target.result.split(",")[1]; 


            c.idCardFile = { 

                name: file.name, 

                type: file.type, 

                data: base64Data 

            }; 


            c.idCardFileName = file.name; 


            if (!c.$$phase) { 

                angular 
                    .element(input) 
                    .scope() 
                    .$apply(); 

            } 

        }; 


        reader.readAsDataURL(file); 

    }; 


    // ========================================= 
    // VERIFY ID 
    // ========================================= 

    c.verifyID = function() { 

        if (c.isSubmitting) { 
            return; 
        } 


       if (
    !c.fullName ||
    !c.email ||
    !c.college ||
    !c.location ||
    !c.skills ||
    !c.interests
) {
    spModal.alert(
        "Please fill in all required information, including Location."
    );
    return;
}


        if (!c.idCardFile) { 

            spModal.alert( 
                "Please upload your college ID card." 
            ); 

            return; 
        } 


        c.isSubmitting = true; 


        c.server.get({ 

            action: "verify_id", 

            fullName: c.fullName, 

            email: c.email, 

            college: c.college,

			location:c.location, 

            skills: c.skills, 

            interests: c.interests, 

            idCardFileName: 
                c.idCardFile.name, 

            idCardFileType: 
                c.idCardFile.type, 

            idCardFileData: 
                c.idCardFile.data 

        }).then(function(response) { 

            c.isSubmitting = false; 


            var result = response.data; 


            if (result.success) { 

                c.verificationSubmitted = true; 

                c.profileSysId = 
                    result.profileSysId; 


                spModal.alert( 
                    "ID verification request submitted successfully.\n\n" + 
                    "Please wait for administrator approval." 
                ); 


                // Start checking approval status 

                c.startApprovalCheck(); 


            } else { 

                spModal.alert( 
                    result.message || 
                    "Unable to submit verification request." 
                ); 

            } 


        }, function() { 

            c.isSubmitting = false; 

            spModal.alert( 
                "Something went wrong while submitting the verification request." 
            ); 

        }); 

    }; 


    // ========================================= 
    // CHECK ADMIN APPROVAL 
    // ========================================= 

    c.checkApprovalStatus = function() { 

        if (!c.profileSysId) { 
            return; 
        } 


        c.server.get({ 

            action: "check_status", 

            profileSysId: 
                c.profileSysId 

        }).then(function(response) { 

            var result = response.data; 


            if (result.status === "verified") { 

                c.idApproved = true; 

                c.stopApprovalCheck(); 

            } 


            if (result.status === "rejected") { 

                c.idApproved = false; 

                c.stopApprovalCheck(); 

                spModal.alert( 
                    "Your ID verification was rejected by the administrator." 
                ); 

            } 

        }); 

    }; 


    // ========================================= 
    // START STATUS CHECK 
    // ========================================= 

    c.startApprovalCheck = function() { 

        c.stopApprovalCheck(); 


        statusTimer = $interval( 
            function() { 

                c.checkApprovalStatus(); 

            }, 
            5000 
        ); 

    }; 


    // ========================================= 
    // STOP STATUS CHECK 
    // ========================================= 

    c.stopApprovalCheck = function() { 

        if (statusTimer) { 

            $interval.cancel(statusTimer); 

            statusTimer = null; 

        } 

    }; 


    // ========================================= 
    // CREATE ACCOUNT
    // ========================================= 

    c.createAccount = function() { 

        if (!c.idApproved) { 

            spModal.alert( 
                "Your ID must be approved by the administrator first." 
            ); 

            return; 
        } 


        if (c.isCreatingAccount) { 
            return; 
        } 


        // ========================================= 
        // PASSWORD VALIDATION
        // ========================================= 

        if (!c.studentPassword || 
            !c.confirmStudentPassword) { 


            return; 
        } 


        if (c.studentPassword !== 
            c.confirmStudentPassword) { 

            spModal.alert( 
                "Password and Confirm Password do not match." 
            ); 

            return; 
        } 


        if (c.studentPassword.length < 8) { 

            spModal.alert( 
                "Password must contain at least 8 characters." 
            ); 

            return; 
        } 


        c.isCreatingAccount = true; 


        // ========================================= 
        // CREATE STUDENT ACCOUNT 
        // ========================================= 

        c.server.get({ 

            action: "create_account", 

            profileSysId: 
                c.profileSysId, 

            password: 
                c.studentPassword 

        }).then(function(response) { 

            c.isCreatingAccount = false; 


            var result = response.data; 


            if (result.success) { 

                spModal.alert( 
                    "Student Account created successfully." 
                ).then(function() { 

                    $window.location.href = 
                        "?id=campus_student_login"; 

                }); 

            } else { 

                spModal.alert( 
                    result.message || 
                    "Unable to create Student Account." 
                ); 

            } 


        }, function() { 

            c.isCreatingAccount = false; 

            spModal.alert( 
                "Something went wrong while creating the account." 
            ); 

        }); 

    }; 


    // Stop timer when leaving page 

    c.$onDestroy = function() { 

        c.stopApprovalCheck(); 

    }; 

};

sp_widget.css:
.student-signup-page {
  min-height: 100vh;
  padding: 40px 16px;
  background: linear-gradient(135deg, #eff6ff, #f8fafc);
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}

.signup-card {
  width: 100%;
  max-width: 620px;
  padding: 36px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  box-shadow: 0 12px 35px rgba(15, 61, 145, 0.10);
  box-sizing: border-box;
}

.signup-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #2563eb;
  background: #eff6ff;
  border-radius: 50%;
  font-size: 30px;
}

.signup-card h1 {
  margin: 0 0 10px;
  color: #0f3d91;
  text-align: center;
  font-size: 28px;
  font-weight: 700;
}

.signup-subtitle {
  margin: 0 0 28px;
  color: #64748b;
  text-align: center;
  line-height: 1.6;
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: #1e293b;
  font-weight: 600;
}

.form-control {
  width: 100%;
  min-height: 46px;
  padding: 11px 13px;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  font-size: 14px;
  box-sizing: border-box;
  transition: border-color .2s, box-shadow .2s;
}

.form-control:focus {
  border-color: #2563eb;
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, .12);
}

.form-group input[type="file"] {
  padding: 10px;
  background: #f8fafc;
}

.form-group small {
  display: block;
  margin-top: 7px;
  color: #64748b;
  line-height: 1.5;
}

.file-selected {
  margin-top: 10px;
  padding: 10px 12px;
  overflow-wrap: anywhere;
  color: #1d4ed8;
  background: #eff6ff;
  border-radius: 7px;
  font-size: 13px;
}

.status-box {
  margin: 22px 0;
  padding: 14px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  color: #334155;
}

.status-pending {
  color: #92400e;
  font-weight: 600;
}

.status-approved {
  color: #15803d;
  font-weight: 700;
}

.verify-id-submit,
.signup-submit {
  width: 100%;
  min-height: 48px;
  padding: 12px 18px;
  border: none;
  border-radius: 8px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background .2s, transform .2s;
}

.verify-id-submit {
  margin-bottom: 12px;
  color: #fff;
  background: #2563eb;
}

.verify-id-submit:hover:not(:disabled) {
  background: #1d4ed8;
}

.signup-submit {
  color: #fff;
  background: #0f3d91;
}

.signup-submit:hover:not(:disabled) {
  background: #0b2f73;
}

.verify-id-submit:disabled,
.signup-submit:disabled {
  opacity: .55;
  cursor: not-allowed;
}

.verification-message {
  margin-top: 18px;
  padding: 13px;
  color: #92400e;
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 8px;
  font-size: 13px;
  line-height: 1.6;
}

.verification-message.approved {
  color: #166534;
  background: #f0fdf4;
  border-color: #bbf7d0;
}

.signup-footer {
  margin-top: 26px;
  padding-top: 20px;
  border-top: 1px solid #e2e8f0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  color: #64748b;
  font-size: 14px;
}

.signup-footer a {
  color: #2563eb;
  font-weight: 600;
  text-decoration: none;
}

.signup-footer a:hover {
  text-decoration: underline;
}

@media (max-width: 700px) {
  .student-signup-page {
    padding: 24px 12px;
  }

  .signup-card {
    padding: 26px 22px;
  }

  .signup-card h1 {
    font-size: 25px;
  }
}

@media (max-width: 450px) {
  .signup-card {
    padding: 22px 16px;
  }

  .signup-card h1 {
    font-size: 23px;
  }

  .status-box {
    align-items: flex-start;
    flex-direction: column;
  }
}

sp_widget.script:
(function() {
    data.success = false;
    data.message = "";
    data.profileSysId = "";
    data.attachmentSysId = "";
    data.status = "";
    data.accountCreated = false;

    var TABLE = "x_snc_campus_con_0_student_profile";

    function fail(message) {
        data.success = false;
        data.message = message;
    }

    function clean(value, maxLength) {
        var result = String(value || "").trim();
        return result.length > maxLength ? "" : result;
    }

    function validEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function getProfile(sysId) {
        var profile = new GlideRecord(TABLE);

        if (!sysId || !profile.get(sysId)) {
            return null;
        }

        return profile;
    }


    // =========================================
    // SUBMIT ID FOR ADMIN REVIEW
    // =========================================

    if (input && input.action === "verify_id") {

        var fullName = clean(input.fullName, 100);
        var email = clean(input.email, 254).toLowerCase();
        var college = clean(input.college, 200);
		var location =clean(input.location,100);
        var skills = clean(input.skills, 1000);
        var interests = clean(input.interests, 1000);

        var fileName = clean(input.idCardFileName, 150);
        var fileType = clean(input.idCardFileType, 100);
        var fileData = String(input.idCardFileData || "");


    if (!fullName ||
    !email ||
    !college ||
    !location ||
    !skills ||
    !interests) {

    fail(
        "Please provide all required information, including Location."
    );

    return;
}


        if (!validEmail(email)) {

            fail(
                "Please enter a valid college email address."
            );

            return;
        }


        if (!fileName || !fileData) {

            fail(
                "Please upload your college ID card."
            );

            return;
        }


        var extension =
            fileName.toLowerCase().split(".").pop();


        var allowed = {
            "jpg": "image/jpeg",
            "jpeg": "image/jpeg",
            "png": "image/png",
            "pdf": "application/pdf"
        };


        if (!allowed[extension] ||
            allowed[extension] !== fileType) {

            fail(
                "Only JPG, JPEG, PNG or PDF files are allowed."
            );

            return;
        }


        // Base64 length limit approximately corresponds to 5 MB.

        if (fileData.length > 7000000 ||
            !/^[A-Za-z0-9+/]*={0,2}$/.test(fileData)) {

            fail(
                "The uploaded file is too large or invalid."
            );

            return;
        }


        // =========================================
        // PREVENT DUPLICATE PROFILE
        // =========================================

        var duplicate =
            new GlideRecord(TABLE);

        duplicate.addQuery(
            "college_email",
            email
        );

        duplicate.setLimit(1);
        duplicate.query();


        if (duplicate.next()) {

            fail(
                "A Student Profile already exists for this email."
            );

            return;
        }


        // =========================================
        // PREVENT DUPLICATE USER
        // =========================================

        var existingUser =
            new GlideRecord("sys_user");

        var emailQuery =
            existingUser.addQuery(
                "email",
                email
            );

        emailQuery.addOrCondition(
            "user_name",
            email
        );

        existingUser.setLimit(1);
        existingUser.query();


        if (existingUser.next()) {

            fail(
                "An account already exists for this email."
            );

            return;
        }


        // =========================================
        // CREATE INACTIVE USER
        // =========================================

        var user =
            new GlideRecord("sys_user");

        user.initialize();

        user.setValue(
            "user_name",
            email
        );

        user.setValue(
            "email",
            email
        );

        user.setValue(
            "first_name",
            fullName
        );

        user.setValue(
            "active",
            false
        );

        user.setValue(
            "password_needs_reset",
            true
        );


        var userSysId =
            user.insert();


        if (!userSysId) {

            fail(
                "Unable to prepare the pending student record."
            );

            return;
        }


        // =========================================
        // CREATE STUDENT PROFILE
        // =========================================

        var profile =
            new GlideRecord(TABLE);

        profile.initialize();


        profile.setValue(
            "unique_registration_number",
            "CC" +
            new GlideDateTime().getNumericValue()
        );


        profile.setValue(
            "student",
            userSysId
        );


        profile.setValue(
            "college_name",
            college
        );


        profile.setValue(
            "college_email",
            email
        );
		profile.setValue(
			"location",
			location
		);


        profile.setValue(
            "skills",
            skills
        );


        profile.setValue(
            "interests",
            interests
        );


        profile.setValue(
            "verification_status",
            "Pending"
        );


        profile.setValue(
            "reliability_score",
            0
        );


        var profileSysId =
            profile.insert();


        if (!profileSysId) {

            // Avoid leaving an orphan inactive user.

            var orphan =
                new GlideRecord("sys_user");

            if (orphan.get(userSysId)) {
                orphan.deleteRecord();
            }


            fail(
                "Unable to create the Student Profile."
            );

            return;
        }


        // =========================================
        // SAVE ID CARD ATTACHMENT
        // =========================================

        var savedProfile =
            new GlideRecord(TABLE);


        if (!savedProfile.get(profileSysId)) {

            fail(
                "The profile was created but could not be retrieved."
            );

            return;
        }


        try {

            var attachment =
                new GlideSysAttachment();


            var attachmentSysId =
                attachment.writeBase64(
                    savedProfile,
                    fileName,
                    fileType,
                    fileData
                );


            if (!attachmentSysId) {

                savedProfile.deleteRecord();


                var cleanupUser =
                    new GlideRecord("sys_user");


                if (cleanupUser.get(userSysId)) {
                    cleanupUser.deleteRecord();
                }


                fail(
                    "ID upload failed. Please try again."
                );

                return;
            }


            // Store attachment reference.

            savedProfile.setValue(
                "id_card_photo",
                attachmentSysId
            );

            savedProfile.update();


            data.success = true;

            data.profileSysId =
                profileSysId;

            data.attachmentSysId =
                attachmentSysId;

            data.message =
                "ID verification request submitted successfully.";


        } catch (e) {

            gs.error(
                "Campus Connect ID upload error: " +
                e.message
            );


            fail(
                "The ID card could not be saved. Please contact the administrator."
            );

        }


        return;
    }


    // =========================================
    // CHECK ADMIN APPROVAL
    // =========================================

    if (input && input.action === "check_status") {

        var checkId =
            String(input.profileSysId || "");


        var checked =
            getProfile(checkId);


        if (!checked) {

            data.status =
                "not_found";

            return;
        }


        data.status =
            String(
                checked.getValue(
                    "verification_status"
                ) || ""
            ).toLowerCase();


        return;
    }


    // =========================================
    // ACTIVATE ACCOUNT AFTER APPROVAL
    // =========================================

    if (input && input.action === "create_account") {

        var requestedId =
            String(
                input.profileSysId || ""
            );


        var approvedProfile =
            getProfile(requestedId);


        if (!approvedProfile) {

            fail(
                "Student Profile could not be found."
            );

            return;
        }


        // =========================================
        // CHECK VERIFICATION STATUS
        // =========================================

        var verificationStatus =
            String(
                approvedProfile.getValue(
                    "verification_status"
                ) || ""
            ).toLowerCase();


        if (verificationStatus !== "verified") {

            fail(
                "Your ID has not been approved by the administrator."
            );

            return;
        }


        // =========================================
        // GET PASSWORD
        // =========================================

        var password =
            String(
                input.password || ""
            );


        if (!password) {

            fail(
                "Please enter a password."
            );

            return;
        }


        if (password.length < 8) {

            fail(
                "Password must contain at least 8 characters."
            );

            return;
        }


        // =========================================
        // GET LINKED USER
        // =========================================

        var linkedUserId =
            String(
                approvedProfile.getValue(
                    "student"
                ) || ""
            );


        if (!linkedUserId) {

            fail(
                "No pending user is linked to this Student Profile."
            );

            return;
        }


        var studentUser =
            new GlideRecord("sys_user");


        if (!studentUser.get(linkedUserId)) {

            fail(
                "The linked student user could not be found."
            );

            return;
        }


        // =========================================
        // VERIFY EMAIL MATCH
        // =========================================

        if (
            studentUser.getValue("email") !==
            approvedProfile.getValue("college_email")
        ) {

            fail(
                "The linked user does not match the registered email."
            );

            return;
        }


        // =========================================
        // CHECK ACCOUNT STATUS
        // =========================================

        if (
            studentUser.getValue("active") ===
            "true"
        ) {

            fail(
                "Your Student Account is already active."
            );

            return;
        }


        // =========================================
        // SET PASSWORD
        // =========================================

        studentUser.user_password.setDisplayValue(password);


        // =========================================
        // ACTIVATE ACCOUNT
        // =========================================

        studentUser.setValue(
            "active",
            true
        );


        studentUser.setValue(
            "password_needs_reset",
            false
        );


        var updated =
            studentUser.update();


        if (!updated) {

            fail(
                "Unable to activate the Student Account."
            );

            return;
        }


        // =========================================
        // SUCCESS
        // =========================================

        data.success = true;

        data.accountCreated = true;

        data.message =
            "Student Account created successfully. You can now login with your college email and password.";

        return;
    }

})();
